package com.vizu.identidade.integracao.service;
import com.fasterxml.jackson.databind.*; import com.vizu.identidade.integracao.dto.EventEnvelope; import java.util.*; import org.springframework.amqp.rabbit.core.RabbitTemplate; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class OutboxService { private final JdbcTemplate jdbc; private final ObjectMapper json; private final RabbitTemplate rabbit; private final String exchange; public OutboxService(JdbcTemplate jdbc,ObjectMapper json,RabbitTemplate rabbit,@Value("${vizu.messaging.exchange}") String exchange){this.jdbc=jdbc;this.json=json;this.rabbit=rabbit;this.exchange=exchange;} public void contratante(UUID id,boolean ativo,String timezone){registrar("identidade.contratante.atualizado.v1","contratante",id,id,null,Map.of("id",id,"ativo",ativo,"timezone",timezone,"versaoEvento",System.currentTimeMillis()));} public void loja(UUID id,UUID tenant,String nome,int capacidade,boolean ativo){registrar("identidade.loja.atualizada.v1","loja",id,tenant,id,Map.of("id",id,"contratanteId",tenant,"nome",nome,"capacidadeSimultanea",capacidade,"ativo",ativo,"versaoEvento",System.currentTimeMillis()));} public void cliente(UUID id,UUID tenant,String nome,String telefone,boolean ativo){registrar("identidade.cliente.atualizado.v1","cliente",id,tenant,null,Map.of("id",id,"contratanteId",tenant,"nome",nome,"telefone",telefone,"ativo",ativo,"versaoEvento",System.currentTimeMillis()));} public void funcionario(UUID id,UUID tenant,String nome,boolean ativo,boolean site){registrar("identidade.funcionario.atualizado.v1","funcionario",id,tenant,null,Map.of("id",id,"contratanteId",tenant,"nome",nome,"ativo",ativo,"exibirNoSite",site,"versaoEvento",System.currentTimeMillis()));} public void funcionarioLoja(UUID funcionario,UUID loja,UUID tenant,boolean ativo){registrar("identidade.funcionario-loja.atualizado.v1","funcionario-loja",funcionario,tenant,loja,Map.of("funcionarioId",funcionario,"lojaId",loja,"contratanteId",tenant,"ativo",ativo,"versaoEvento",System.currentTimeMillis()));} public void registrar(String tipo,String aggregate,UUID aggregateId,UUID tenant,UUID loja,Object payload){jdbc.update("INSERT INTO identidade.outbox_event(event_id,event_type,aggregate_type,aggregate_id,contratante_id,loja_id,payload) VALUES(?,?,?,?,?,?,?::jsonb)",UUID.randomUUID(),tipo,aggregate,aggregateId,tenant,loja,json.valueToTree(payload).toString());} @Scheduled(fixedDelayString="${vizu.messaging.outbox-interval-ms}") @Transactional public void publicar(){for(Map<String,Object> row:jdbc.queryForList("SELECT event_id,event_type,payload FROM identidade.outbox_event WHERE publicado_em IS NULL ORDER BY ocorrido_em LIMIT 100"))try{UUID id=(UUID)row.get("event_id");String type=(String)row.get("event_type");JsonNode payload=json.readTree((String)row.get("payload"));rabbit.convertAndSend(exchange,type,new EventEnvelope(id,type,payload));jdbc.update("UPDATE identidade.outbox_event SET publicado_em=now(),ultimo_erro=null WHERE event_id=?",id);}catch(Exception e){jdbc.update("UPDATE identidade.outbox_event SET tentativas=tentativas+1,ultimo_erro=? WHERE event_id=?",e.getMessage(),row.get("event_id"));}} }
